use serde_json::json;
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,path::Path,process::Command};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn check(pristine:&Path,actual:&Path,pins:&mut BTreeMap<String,String>){if pristine.is_dir(){for e in fs::read_dir(pristine).unwrap(){let p=e.unwrap().path();check(&p,&actual.join(p.file_name().unwrap()),pins)}}else{assert_eq!(fs::read(pristine).unwrap(),fs::read(actual).unwrap(),"registry source differs {}",actual.display());pins.insert(actual.to_str().unwrap().into(),hash(actual));}}
fn main(){let root=Path::new("/tmp/zopro-front-snapshot-fence");let dst=root.join("registry-pristine");assert!(!dst.exists());fs::create_dir(&dst).unwrap();let cache=Path::new("/home/ubuntu/.cargo/registry/cache/index.crates.io-1949cf8c6b5b557f");let registry=Path::new("/home/ubuntu/.cargo/registry/src/index.crates.io-1949cf8c6b5b557f");let mut pins=BTreeMap::new();for name in ["crossbeam-deque-0.8.8","crossbeam-epoch-0.9.21","crossbeam-utils-0.8.23","rayon-core-1.13.0"]{let archive=cache.join(format!("{name}.crate"));assert!(Command::new("tar").arg("-xf").arg(&archive).arg("-C").arg(&dst).status().unwrap().success());pins.insert(archive.to_str().unwrap().into(),hash(&archive));for member in ["src","build.rs","Cargo.toml"]{check(&dst.join(name).join(member),&registry.join(name).join(member),&mut pins);}}
fs::write(root.join("registry-input-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(root.join("registry-audit.json"),serde_json::to_vec_pretty(&json!({"status":"passed","source_files_and_archive_pins":pins.len(),"packages":["crossbeam-deque0.8.8","crossbeam-epoch0.9.21","crossbeam-utils0.8.23","rayon-core1.13.0"],"scope":"Actual registry src trees, build scripts and normalized manifests byte-checked against pristine archive extraction. Runtime candidate uses privately patched deque; registry deque is the accepted-source reference. No registry writes."})).unwrap()).unwrap();println!("REGISTRY_SOURCE_VERIFIED {} files/archive pins",pins.len());}
